uname -r; cat /sys/kernel/realtime /sys/devices/system/cpu/online; sha256sum /media/sd-mmcblk1p1/image.ub; ps | grep -E "[c]yclictest|[r]tload|[p]erf (stat|record)"; for p in /sys/kernel/tracing/instances/rt-audit /sys/kernel/tracing/instances/rt-audit-idle2; do echo "$p"; cat "$p/tracing_on" "$p/events/enable"; done; cat /sys/kernel/tracing/current_tracer /sys/kernel/tracing/tracing_on /sys/kernel/tracing/events/enable; cat /proc/meminfo | head -n 3; dmesg
